#include "fstr/native_scene.hpp"
#include "fstr/automatic_scene_cache.hpp"
#include "json.hpp"
#include <fstream>
#include <filesystem>
#include <iostream>
int main(int argc,char**argv){try{if(argc!=9)throw std::invalid_argument("resources width height source-height rgba8 cache-dir output-prefix mode");fstr::NativeSceneAnalyzer model(argv[1]);int calls=0;fstr::AutomaticSceneCache cache(argv[6],model.policy(),[&](const auto&i,double h,const auto&c){++calls;return model.analyze(i,h,c);});fstr::AnalysisImage image;image.width=std::stoi(argv[2]);image.height=std::stoi(argv[3]);if(image.width<1||image.height<1||image.width>384||image.height>384)throw std::invalid_argument("Input size");image.rgba.resize(std::size_t(image.width)*std::size_t(image.height)*4);std::ifstream input(argv[5],std::ios::binary);input.read(reinterpret_cast<char*>(image.rgba.data()),std::streamsize(image.rgba.size()));if(!input||input.peek()!=EOF)throw std::runtime_error("Input size mismatch");auto result=cache.get(image,std::stod(argv[4]));if(std::string(argv[8])=="repeat"){cache.get(image,std::stod(argv[4]));cache.clear_memory();cache.get(image,std::stod(argv[4]));}std::filesystem::path out(argv[7]);auto write=[](const std::filesystem::path&p,const std::vector<float>&v){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(v.data()),std::streamsize(v.size()*4));if(!f)throw std::runtime_error("Output failed");};std::vector<float> roles;for(auto w:result->scene)roles.insert(roles.end(),w.begin(),w.end());write(out.string()+".roles",roles);nlohmann::json people=nlohmann::json::array();for(std::size_t i=0;i<result->people.size();++i){const auto&p=result->people[i];auto prefix=out.string()+"-p"+std::to_string(i);write(prefix+".mask",p.mask);write(prefix+".support",p.toning_support);std::vector<float> samples;for(const auto&s:p.samples)for(double v:{s.color.r,s.color.g,s.color.b,s.confidence})samples.push_back(float(v));write(prefix+".samples",samples);people.push_back({{"box",p.box},{"confidence",p.detection_confidence},{"strength",p.toning_strength},{"descriptor",p.descriptor},{"samples",p.samples.size()}});}std::ofstream report(out.string()+".json");report<<nlohmann::json{{"policy",model.policy()},{"computes",calls},{"people",people},{"width",result->width},{"height",result->height}}.dump(2);std::cout<<"native analysis: "<<people.size()<<" people; "<<calls<<" inference passes\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
